00109   unsigned sigCtxIdAbs( int scanPos, const TCoeff* coeff, const int state )
00110   {
00111     const uint32_t posY      = m_scan[scanPos].y;
00112     const uint32_t posX      = m_scan[scanPos].x;
00113     const TCoeff* pData     = coeff + posX + posY * m_width;
00114     const int     diag      = posX + posY;
00115     int           numPos    = 0;
00116     TCoeff        sumAbs    = 0;
00117 #define UPDATE(x) {TCoeff a=abs(x);sumAbs+=std::min(4+(a&1),a);numPos+=int(!!a);}
00118     if( posX < m_width-1 )
00119     {
00120       UPDATE( pData[1] );
00121       if( posX < m_width-2 )
00122       {
00123         UPDATE( pData[2] );
00124       }
00125       if( posY < m_height-1 )
00126       {
00127         UPDATE( pData[m_width+1] );
00128       }
00129     }
00130     if( posY < m_height-1 )
00131     {
00132       UPDATE( pData[m_width] );
00133       if( posY < m_height-2 )
00134       {
00135         UPDATE( pData[m_width<<1] );
00136       }
00137     }
00138 #undef UPDATE
00139 
00140 
00141     int ctxOfs = int(std::min<TCoeff>((sumAbs+1)>>1, 3)) + ( diag < 2 ? 4 : 0 );
00142 
00143     if( m_chType == CHANNEL_TYPE_LUMA )
00144     {
00145       ctxOfs += diag < 5 ? 4 : 0;
00146     }
00147 
00148     m_tmplCpDiag = diag;
00149     m_tmplCpSum1 = sumAbs - numPos;
00150     return m_sigFlagCtxSet[std::max( 0, state-1 )]( ctxOfs );
00151   }
00152 
00153   uint8_t ctxOffsetAbs()
00154   {
00155     int offset = 0;
00156     if( m_tmplCpDiag != -1 )
00157     {
00158       offset  = int(std::min<TCoeff>( m_tmplCpSum1, 4 )) + 1;
00159       offset += ( !m_tmplCpDiag ? ( m_chType == CHANNEL_TYPE_LUMA ? 15 : 5 ) : m_chType == CHANNEL_TYPE_LUMA ? m_tmplCpDiag < 3 ? 10 : ( m_tmplCpDiag < 10 ? 5 : 0 ) : 0 );
00160     }
00161     return uint8_t(offset);
00162   }
00163 
00164   unsigned parityCtxIdAbs   ( uint8_t offset )  const { return m_parFlagCtxSet   ( offset ); }
00165   unsigned greater1CtxIdAbs ( uint8_t offset )  const { return m_gtxFlagCtxSet[1]( offset ); }
00166   unsigned greater2CtxIdAbs ( uint8_t offset )  const { return m_gtxFlagCtxSet[0]( offset ); }
00167   unsigned templateAbsSum( int scanPos, const TCoeff* coeff, int baseLevel )
00168   {
00169     const uint32_t  posY  = m_scan[scanPos].y;
00170     const uint32_t  posX  = m_scan[scanPos].x;
00171     const TCoeff*   pData = coeff + posX + posY * m_width;
00172     TCoeff          sum   = 0;
00173     if (posX < m_width - 1)
00174     {
00175       sum += abs(pData[1]);
00176       if (posX < m_width - 2)
00177       {
00178         sum += abs(pData[2]);
00179       }
00180       if (posY < m_height - 1)
00181       {
00182         sum += abs(pData[m_width + 1]);
00183       }
00184     }
00185     if (posY < m_height - 1)
00186     {
00187       sum += abs(pData[m_width]);
00188       if (posY < m_height - 2)
00189       {
00190         sum += abs(pData[m_width << 1]);
00191       }
00192     }
00193     return unsigned(std::max<TCoeff>(std::min<TCoeff>(sum - 5 * baseLevel, 31), 0));
00194   }
