00196   unsigned sigCtxIdAbsTS( int scanPos, const TCoeff* coeff )
00197   {
00198     const uint32_t  posY   = m_scan[scanPos].y;
00199     const uint32_t  posX   = m_scan[scanPos].x;
00200     const TCoeff*   posC   = coeff + posX + posY * m_width;
00201     int             numPos = 0;
00202 #define UPDATE(x) {TCoeff a=abs(x);numPos+=int(!!a);}
00203     if( posX > 0 )
00204     {
00205       UPDATE( posC[-1] );
00206     }
00207     if( posY > 0 )
00208     {
00209       UPDATE( posC[-(int)m_width] );
00210     }
00211 #undef UPDATE
00212 
00213     return m_tsSigFlagCtxSet( numPos );
00214   }
