00219   unsigned lrg1CtxIdAbsTS(int scanPos, const TCoeff* coeff, int bdpcm)
00220   {
00221     const uint32_t  posY = m_scan[scanPos].y;
00222     const uint32_t  posX = m_scan[scanPos].x;
00223     const TCoeff*   posC = coeff + posX + posY * m_width;
00224 
00225     int             numPos = 0;
00226 #define UPDATE(x) {TCoeff a=abs(x);numPos+=int(!!a);}
00227 
00228     if (bdpcm)
00229     {
00230       numPos = 3;
00231     }
00232     else
00233     {
00234       if (posX > 0)
00235       {
00236         UPDATE(posC[-1]);
00237       }
00238       if (posY > 0)
00239       {
00240         UPDATE(posC[-(int)m_width]);
00241       }
00242     }
00243 
00244 #undef UPDATE
00245     return m_tsLrg1FlagCtxSet(numPos);
00246   }
