00248   template <typename T> int sgn(T val)
00249   {
00250     return (T(0) < val) - (val < T(0));
00251   }
00252 
00253   unsigned signCtxIdAbsTS(int scanPos, const TCoeff* coeff, int bdpcm)
00254   {
00255     const uint32_t  posY = m_scan[scanPos].y;
00256     const uint32_t  posX = m_scan[scanPos].x;
00257     const TCoeff*   pData = coeff + posX + posY * m_width;
00258 
00259     int rightSign = 0, belowSign = 0;
00260     unsigned signCtx = 0;
00261 
00262     if (posX > 0)
00263     {
00264       rightSign = sgn(pData[-1]);
00265     }
00266     if (posY > 0)
00267     {
00268       belowSign = sgn(pData[-(int)m_width]);
00269     }
00270 
00271     if ((rightSign == 0 && belowSign == 0) || ((rightSign*belowSign) < 0))
00272     {
00273       signCtx = 0;
00274     }
00275     else if (rightSign >= 0 && belowSign >= 0)
00276     {
00277       signCtx = 1;
00278     }
00279     else
00280     {
00281       signCtx = 2;
00282     }
00283     if (bdpcm)
00284     {
00285       signCtx += 3;
00286     }
00287     return m_tsSignFlagCtxSet(signCtx);
00288   }
00289 
00290   void neighTS(int &rightPixel, int &belowPixel, int scanPos, const TCoeff* coeff)
00291   {
00292     const uint32_t  posY = m_scan[scanPos].y;
00293     const uint32_t  posX = m_scan[scanPos].x;
00294     const TCoeff*   data = coeff + posX + posY * m_width;
00295 
00296     rightPixel = belowPixel = 0;
00297 
00298     if (posX > 0)
00299     {
00300       rightPixel = int(data[-1]);
00301     }
00302     if (posY > 0)
00303     {
00304       belowPixel = int(data[-(int)m_width]);
00305     }
00306   }
00307 
00308   int deriveModCoeff(int rightPixel, int belowPixel, TCoeff absCoeff, int bdpcm = 0)
00309   {
00310 
00311     if (absCoeff == 0)
00312       return 0;
00313     int pred1, absBelow = abs(belowPixel), absRight = abs(rightPixel);
00314 
00315     int absCoeffMod = int(absCoeff);
00316 
00317     if (bdpcm == 0)
00318     {
00319       pred1 = std::max(absBelow, absRight);
00320 
00321       if (absCoeffMod == pred1)
00322       {
00323         absCoeffMod = 1;
00324       }
00325       else
00326       {
00327         absCoeffMod = absCoeffMod < pred1 ? absCoeffMod + 1 : absCoeffMod;
00328       }
00329     }
00330 
00331     return(absCoeffMod);
00332   }
00333 
00334   TCoeff decDeriveModCoeff(int rightPixel, int belowPixel, TCoeff absCoeff)
00335   {
00336 
00337     if (absCoeff == 0)
00338       return 0;
00339 
00340     int pred1, absBelow = abs(belowPixel), absRight = abs(rightPixel);
00341     pred1 = std::max(absBelow, absRight);
00342 
00343     TCoeff absCoeffMod;
00344 
00345     if (absCoeff == 1 && pred1 > 0)
00346     {
00347       absCoeffMod = pred1;
00348     }
00349     else
00350     {
00351       absCoeffMod = absCoeff - (absCoeff <= pred1);
00352     }
00353     return(absCoeffMod);
00354   }
